import { env, exports } from 'cloudflare:workers'
import { ExternalTokenError } from '@cloudflare/workers-oauth-provider'
import { http, HttpResponse } from 'msw'
import { afterEach, describe, expect, it, vi } from 'vitest'
import {
  buildAuthProps,
  cloudflareTokenOwner,
  resolveExternalToken
} from '../../src/auth/api-token-mode'
import { AUTH_PROPS_VERSION } from '../../src/auth/types'
import { API_BASE, cfAccountsSuccess, cfError, cfSuccess } from '../helpers/cloudflare-api'
import { clearKv } from '../helpers/kv'
import { MCP_URL, modernMcpRequest } from '../helpers/mcp'
import { server } from '../setup/msw'

vi.mock('../../src/utils/fetch-retry', async (importOriginal) => {
  const original = await importOriginal<typeof import('../../src/utils/fetch-retry')>()
  return {
    ...original,
    fetchWithRetry: (input: RequestInfo, init?: RequestInit) =>
      original.fetchWithRetry(input, init, { maxRetries: 0 })
  }
})

const USER = { id: 'user-1', email: 'user@example.com' }
const ACCOUNT = { id: 'account-1', name: 'Account One' }

function resolverInput(token: string) {
  return {
    token,
    request: new Request(MCP_URL),
    env
  }
}

async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value))
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

function mockIdentity(opts: { user?: () => Response; accounts?: () => Response }): {
  userCalls: () => number
  accountCalls: () => number
} {
  let userCalls = 0
  let accountCalls = 0
  if (opts.user) {
    server.use(
      http.get(`${API_BASE}/user`, () => {
        userCalls++
        return opts.user!()
      })
    )
  }
  if (opts.accounts) {
    server.use(
      http.get(`${API_BASE}/accounts`, () => {
        accountCalls++
        return opts.accounts!()
      })
    )
  }
  return { userCalls: () => userCalls, accountCalls: () => accountCalls }
}

async function expectExternalTokenError(
  promise: Promise<unknown>,
  code: string,
  statusCode: number
): Promise<ExternalTokenError> {
  try {
    await promise
    throw new Error('Expected ExternalTokenError')
  } catch (error) {
    expect(error).toBeInstanceOf(ExternalTokenError)
    expect(error).toMatchObject({ code, statusCode })
    return error as ExternalTokenError
  }
}

afterEach(() => clearKv(env.OAUTH_KV))

describe('Cloudflare token ownership', () => {
  it.each([
    ['cfat_account-token', 'account'],
    ['cfut_user-token', 'user'],
    ['cfoat_wrangler-token', 'user'],
    ['legacy-unprefixed-token', 'unknown']
  ] as const)('classifies %s as %s', (token, owner) => {
    expect(cloudflareTokenOwner(token)).toBe(owner)
  })
})

describe('buildAuthProps', () => {
  it('builds versioned user props', () => {
    expect(
      buildAuthProps('token', {
        type: 'user',
        user: USER,
        accounts: [ACCOUNT],
        accountCount: 1
      })
    ).toEqual({
      type: 'user_token',
      accessToken: 'token',
      user: USER,
      accounts: [ACCOUNT],
      accountCount: 1,
      version: AUTH_PROPS_VERSION
    })
  })

  it('builds account props from an account identity', () => {
    expect(buildAuthProps('token', { type: 'account', account: ACCOUNT })).toEqual({
      type: 'account_token',
      accessToken: 'token',
      account: ACCOUNT
    })
  })
})

describe('resolveExternalToken', () => {
  it('uses only /accounts for prefixed account tokens', async () => {
    const calls = mockIdentity({
      user: () => HttpResponse.json(cfSuccess(USER)),
      accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
    })

    await expect(resolveExternalToken(resolverInput('cfat_account-token'))).resolves.toEqual({
      props: {
        type: 'account_token',
        accessToken: 'cfat_account-token',
        account: ACCOUNT
      },
      audience: env.MCP_RESOURCE
    })
    expect(calls.userCalls()).toBe(0)
    expect(calls.accountCalls()).toBe(1)
  })

  it.each(['cfut_user-token', 'cfoat_wrangler-token'])(
    'uses /user and /accounts for prefixed user credential %s',
    async (token) => {
      const calls = mockIdentity({
        user: () => HttpResponse.json(cfSuccess(USER)),
        accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
      })

      await expect(resolveExternalToken(resolverInput(token))).resolves.toMatchObject({
        props: { type: 'user_token', accessToken: token, user: USER, accounts: [ACCOUNT] },
        audience: env.MCP_RESOURCE
      })
      expect(calls.userCalls()).toBe(1)
      expect(calls.accountCalls()).toBe(1)
    }
  )

  it('retains response-based account inference for legacy credentials', async () => {
    const calls = mockIdentity({
      user: () => HttpResponse.json(cfError([], null), { status: 403 }),
      accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
    })

    await expect(
      resolveExternalToken(resolverInput('legacy-account-token'))
    ).resolves.toMatchObject({
      props: { type: 'account_token', account: ACCOUNT }
    })
    expect(calls.userCalls()).toBe(1)
    expect(calls.accountCalls()).toBe(1)
  })

  it('does not infer account ownership for a known user token', async () => {
    mockIdentity({
      user: () => HttpResponse.json(cfError([], null), { status: 403 }),
      accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
    })

    const error = await expectExternalTokenError(
      resolveExternalToken(resolverInput('cfut_user-token-no-user-scope')),
      'insufficient_scope',
      403
    )
    expect(error.requiredScopes).toEqual(['user:read', 'account:read'])
  })

  it('uses account-only scope guidance for account token failures', async () => {
    const calls = mockIdentity({
      user: () => HttpResponse.json(cfSuccess(USER)),
      accounts: () => HttpResponse.json(cfError([], null), { status: 403 })
    })

    const error = await expectExternalTokenError(
      resolveExternalToken(resolverInput('cfat_account-token-no-read-scope')),
      'insufficient_scope',
      403
    )
    expect(error.requiredScopes).toEqual(['account:read'])
    expect(calls.userCalls()).toBe(0)
    expect(calls.accountCalls()).toBe(1)
  })

  it('caches a verified identity by token hash', async () => {
    const calls = mockIdentity({
      user: () => HttpResponse.json(cfSuccess(USER)),
      accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
    })
    const input = resolverInput('cfut_cached-user-token')

    await resolveExternalToken(input)
    await resolveExternalToken(input)

    expect(calls.userCalls()).toBe(1)
    expect(calls.accountCalls()).toBe(1)
  })

  it('ignores malformed cached identity data and revalidates upstream', async () => {
    const token = 'cfut_invalid-cache-token'
    await env.OAUTH_KV.put(
      `api-token-identity:v4:${await sha256Hex(token)}`,
      JSON.stringify({ user: 'not-an-object', accounts: [] })
    )
    const calls = mockIdentity({
      user: () => HttpResponse.json(cfSuccess(USER)),
      accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
    })

    await expect(resolveExternalToken(resolverInput(token))).resolves.toMatchObject({
      props: { type: 'user_token', user: USER, accounts: [ACCOUNT] }
    })
    expect(calls.userCalls()).toBe(1)
    expect(calls.accountCalls()).toBe(1)
  })

  it('maps malformed credentials to invalid_token', async () => {
    mockIdentity({
      user: () => HttpResponse.json(cfError([], null), { status: 400 }),
      accounts: () => HttpResponse.json(cfError([], null), { status: 400 })
    })

    const error = await expectExternalTokenError(
      resolveExternalToken(resolverInput('malformed-token')),
      'invalid_token',
      401
    )
    expect(error.description).toContain('appears malformed')
  })

  it('preserves rate-limit backoff', async () => {
    mockIdentity({
      user: () =>
        HttpResponse.json(cfError([], null), {
          status: 429,
          headers: { 'Retry-After': '17' }
        }),
      accounts: () => HttpResponse.json(cfError([], null), { status: 429 })
    })

    const error = await expectExternalTokenError(
      resolveExternalToken(resolverInput('cfoat_rate-limited-token')),
      'temporarily_unavailable',
      429
    )
    expect(error.headers).toEqual({ 'Retry-After': '17' })
  })

  it('maps upstream failures to server_error', async () => {
    mockIdentity({
      user: () => HttpResponse.json(cfError([], null), { status: 502 }),
      accounts: () => HttpResponse.json(cfError([], null), { status: 401 })
    })

    await expectExternalTokenError(
      resolveExternalToken(resolverInput('legacy-upstream-failure')),
      'server_error',
      502
    )
  })
})

describe('external token resource responses', () => {
  it('lets the provider construct the RFC 6750/9728 invalid-token response', async () => {
    mockIdentity({
      user: () => HttpResponse.json(cfError([], null), { status: 400 }),
      accounts: () => HttpResponse.json(cfError([], null), { status: 400 })
    })

    const response = await exports.default.fetch(
      modernMcpRequest('malformed-provider-token', 'server/discover')
    )

    expect(response.status).toBe(401)
    expect(response.headers.get('cache-control')).toBe('no-store')
    expect(response.headers.get('www-authenticate')).toContain('error="invalid_token"')
    expect(response.headers.get('www-authenticate')).toContain(
      `resource_metadata="${new URL(MCP_URL).origin}/.well-known/oauth-protected-resource/mcp"`
    )
    await expect(response.json()).resolves.toEqual({
      error: 'invalid_token',
      error_description: 'Access token appears malformed; reauthenticate and try again'
    })
  })

  it('lets the provider construct an insufficient-scope challenge', async () => {
    mockIdentity({
      user: () => HttpResponse.json(cfError([], null), { status: 403 }),
      accounts: () => HttpResponse.json(cfAccountsSuccess([ACCOUNT]))
    })

    const response = await exports.default.fetch(
      modernMcpRequest('cfut_provider-insufficient-scope', 'server/discover')
    )

    expect(response.status).toBe(403)
    expect(response.headers.get('www-authenticate')).toContain('error="insufficient_scope"')
    expect(response.headers.get('www-authenticate')).toContain('scope="user:read account:read"')
    await expect(response.json()).resolves.toEqual({
      error: 'insufficient_scope',
      error_description: 'Token lacks required user:read or account:read scope'
    })
  })

  it('lets the provider preserve a retryable rate-limit response', async () => {
    mockIdentity({
      user: () =>
        HttpResponse.json(cfError([], null), {
          status: 429,
          headers: { 'Retry-After': '23' }
        }),
      accounts: () => HttpResponse.json(cfError([], null), { status: 429 })
    })

    const response = await exports.default.fetch(
      modernMcpRequest('cfoat_provider-rate-limit', 'server/discover')
    )

    expect(response.status).toBe(429)
    expect(response.headers.get('retry-after')).toBe('23')
    expect(response.headers.get('cache-control')).toBe('no-store')
    await expect(response.json()).resolves.toEqual({
      error: 'temporarily_unavailable',
      error_description: 'Rate limited, try again later'
    })
  })
})

import { env, exports } from 'cloudflare:workers'
import { http, HttpResponse } from 'msw'
import { afterEach, describe, expect, it } from 'vitest'
import { cfAccountsSuccess, cfSuccess } from '../helpers/cloudflare-api'
import { clearKv } from '../helpers/kv'
import { modernMcpRequest, parseMcpResult } from '../helpers/mcp'
import { server } from '../setup/msw'

const MCP_ORIGIN = 'https://mcp.cloudflare.com'
const MCP_RESOURCE = `${MCP_ORIGIN}/mcp`
const REDIRECT_URI = 'https://client.example.com/callback'
const CIMD_CLIENT_ID = 'https://client.example.com/oauth/client.json'
const DOWNSTREAM_CODE_VERIFIER = 'test-downstream-code-verifier'
const DOWNSTREAM_CODE_CHALLENGE = 'I4fhllfHqqQsgap17V2SDI0scSei8H7U0e0rZBDIcbo'

function cimdMetadata(clientId = CIMD_CLIENT_ID, redirectUri = REDIRECT_URI) {
  return {
    client_id: clientId,
    client_name: 'CIMD Test Client',
    client_uri: 'https://client.example.com',
    redirect_uris: [redirectUri],
    grant_types: ['authorization_code', 'refresh_token'],
    response_types: ['code'],
    token_endpoint_auth_method: 'none'
  }
}

function authorizeUrl(
  clientId = CIMD_CLIENT_ID,
  redirectUri = REDIRECT_URI,
  resource = MCP_RESOURCE
): string {
  const url = new URL(`${MCP_ORIGIN}/authorize`)
  url.search = new URLSearchParams({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: redirectUri,
    resource,
    scope: 'user:read',
    state: 'client-state',
    code_challenge: DOWNSTREAM_CODE_CHALLENGE,
    code_challenge_method: 'S256'
  }).toString()
  return url.href
}

function cookiesFrom(response: Response): string {
  const values = response.headers.getSetCookie?.() ?? [response.headers.get('set-cookie') ?? '']
  return values
    .filter(Boolean)
    .map((value) => value.split(';')[0])
    .join('; ')
}

function useCloudflareAuthSuccess(): void {
  server.use(
    http.post('https://dash.cloudflare.com/oauth2/token', () =>
      HttpResponse.json({
        access_token: 'access-token',
        expires_in: 3600,
        refresh_token: 'refresh-token',
        scope: 'user:read account:read offline_access',
        token_type: 'bearer'
      })
    ),
    http.get('https://api.cloudflare.com/client/v4/user', () =>
      HttpResponse.json(cfSuccess({ id: 'user-1', email: 'user@example.com' }))
    ),
    http.get('https://api.cloudflare.com/client/v4/accounts', () =>
      HttpResponse.json(cfAccountsSuccess([{ id: 'acc-1', name: 'Account One' }]))
    )
  )
}

afterEach(async () => {
  await clearKv(env.OAUTH_KV)
})

describe('Client ID Metadata Documents', () => {
  it('advertises CIMD while retaining dynamic registration fallback', async () => {
    const response = await exports.default.fetch(
      new Request(`${MCP_ORIGIN}/.well-known/oauth-authorization-server`)
    )

    expect(response.status).toBe(200)
    await expect(response.json()).resolves.toMatchObject({
      client_id_metadata_document_supported: true,
      registration_endpoint: `${MCP_ORIGIN}/register`
    })
  })

  it('completes a public-client flow without persisting a phantom client', async () => {
    let metadataFetches = 0
    server.use(
      http.get(CIMD_CLIENT_ID, () => {
        metadataFetches++
        return HttpResponse.json(cimdMetadata())
      })
    )

    const authorization = await exports.default.fetch(new Request(authorizeUrl()))
    expect(authorization.status).toBe(200)
    const html = await authorization.text()
    expect(html).toContain('CIMD Test Client')

    const handle = html.match(/name="handle" value="([^"]+)"/)?.[1]
    expect(handle).toBeTruthy()

    const approval = await exports.default.fetch(
      new Request(`${MCP_ORIGIN}/authorize`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Cookie: cookiesFrom(authorization)
        },
        body: new URLSearchParams({ handle: handle!, scopes: 'user:read' }).toString(),
        redirect: 'manual'
      })
    )
    expect(approval.status).toBe(302)
    const upstreamState = new URL(approval.headers.get('location')!).searchParams.get('state')
    expect(upstreamState).toBeTruthy()

    useCloudflareAuthSuccess()
    const callback = await exports.default.fetch(
      new Request(
        `${MCP_ORIGIN}/oauth/callback?code=authcode&state=${encodeURIComponent(upstreamState!)}`,
        { headers: { Cookie: cookiesFrom(approval) }, redirect: 'manual' }
      )
    )
    expect(callback.status).toBe(302)
    const redirect = new URL(callback.headers.get('location')!)
    expect(redirect.origin + redirect.pathname).toBe(REDIRECT_URI)
    expect(redirect.searchParams.get('state')).toBe('client-state')
    expect(redirect.searchParams.get('iss')).toBe(MCP_ORIGIN)
    const code = redirect.searchParams.get('code')
    expect(code).toBeTruthy()

    const tokenResponse = await exports.default.fetch(
      new Request(`${MCP_ORIGIN}/token`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          grant_type: 'authorization_code',
          code: code!,
          client_id: CIMD_CLIENT_ID,
          redirect_uri: REDIRECT_URI,
          code_verifier: DOWNSTREAM_CODE_VERIFIER,
          resource: MCP_RESOURCE
        }).toString()
      })
    )
    expect(tokenResponse.status).toBe(200)
    const tokens = (await tokenResponse.json()) as { access_token: string; resource: string }
    expect(tokens.resource).toBe(MCP_RESOURCE)

    const mcpResponse = await exports.default.fetch(
      modernMcpRequest(tokens.access_token, 'tools/list')
    )
    const mcpBody = await parseMcpResult(mcpResponse)
    expect(mcpResponse.status).toBe(200)
    expect(mcpBody.result?.tools?.map((tool) => tool.name)).toEqual([
      'docs',
      'search',
      'execute',
      'whoami'
    ])

    expect(metadataFetches).toBeGreaterThan(0)
    expect((await env.OAUTH_KV.list({ prefix: 'client:' })).keys).toHaveLength(0)
  })

  it('returns a local retryable error when metadata cannot be fetched', async () => {
    const unavailableClientId = 'https://unavailable.example.com/oauth/client.json'
    server.use(http.get(unavailableClientId, () => new HttpResponse(null, { status: 502 })))

    const response = await exports.default.fetch(new Request(authorizeUrl(unavailableClientId)), {
      redirect: 'manual'
    })

    expect(response.status).toBe(503)
    expect(response.headers.get('location')).toBeNull()
    expect(response.headers.get('retry-after')).toBe('30')
    expect(await response.text()).toContain('Client metadata is temporarily unavailable')
    expect((await env.OAUTH_KV.list({ prefix: 'grant:' })).keys).toHaveLength(0)
    expect((await env.OAUTH_KV.list({ prefix: 'client:' })).keys).toHaveLength(0)
  })

  it.each([
    'http://remote-client.example/callback',
    'ftp://remote-client.example/callback',
    'com.example.client:/callback'
  ])('rejects a non-HTTPS, non-loopback redirect URI locally: %s', async (redirectUri) => {
    server.use(
      http.get(CIMD_CLIENT_ID, () => HttpResponse.json(cimdMetadata(CIMD_CLIENT_ID, redirectUri)))
    )

    const response = await exports.default.fetch(
      new Request(authorizeUrl(CIMD_CLIENT_ID, redirectUri)),
      { redirect: 'manual' }
    )

    expect(response.status).toBe(400)
    expect(response.headers.get('location')).toBeNull()
    // workers-oauth-provider 1.2 refuses the request's redirect URI itself, before our own check.
    expect(await response.text()).toContain('Invalid redirect URI')
    expect((await env.OAUTH_KV.list({ prefix: 'grant:' })).keys).toHaveLength(0)
  })

  it('never sends an authorization error to an unsafe redirect URI', async () => {
    const redirectUri = 'http://remote-client.example/callback'
    server.use(
      http.get(CIMD_CLIENT_ID, () => HttpResponse.json(cimdMetadata(CIMD_CLIENT_ID, redirectUri)))
    )

    const response = await exports.default.fetch(
      new Request(authorizeUrl(CIMD_CLIENT_ID, redirectUri, MCP_ORIGIN)),
      { redirect: 'manual' }
    )

    expect(response.status).toBe(400)
    expect(response.headers.get('location')).toBeNull()
    // The redirect URI is refused before the resource is checked, so no error can reach it.
    expect(await response.text()).toContain('Invalid redirect URI')
    expect((await env.OAUTH_KV.list({ prefix: 'grant:' })).keys).toHaveLength(0)
  })

  it('shows the verified client ID and warns about a local redirect on the consent page', async () => {
    const loopbackRedirect = 'http://127.0.0.1:3210/callback'
    server.use(
      http.get(CIMD_CLIENT_ID, () =>
        HttpResponse.json({ ...cimdMetadata(), redirect_uris: [REDIRECT_URI, loopbackRedirect] })
      )
    )

    const response = await exports.default.fetch(
      new Request(authorizeUrl(CIMD_CLIENT_ID, loopbackRedirect))
    )

    expect(response.status).toBe(200)
    const html = await response.text()
    // describeConsent() supplies the name, the CIMD client ID and the loopback flag.
    expect(html).toContain('CIMD Test Client')
    expect(html).toContain('Client ID</span>')
    expect(html).toContain('client.example.com<span class="url-dim">/<wbr>oauth/<wbr>client.json')
    expect(html).toContain('Local redirect:')
  })

  it('resolves a document that also lists a redirect URI the policy refuses', async () => {
    // A metadata document is shared by every server the client uses, so it may list a
    // desktop app's private-use callback next to its https one.
    server.use(
      http.get(CIMD_CLIENT_ID, () =>
        HttpResponse.json({
          ...cimdMetadata(),
          redirect_uris: [REDIRECT_URI, 'com.example.client:/callback']
        })
      )
    )

    const response = await exports.default.fetch(new Request(authorizeUrl()))

    expect(response.status).toBe(200)
    expect(await response.text()).toContain('name="handle"')
  })

  it('requires a fresh authorization when metadata fails during the callback', async () => {
    let metadataFetches = 0
    server.use(
      http.get(CIMD_CLIENT_ID, () => {
        metadataFetches++
        return metadataFetches <= 2
          ? HttpResponse.json(cimdMetadata())
          : new HttpResponse(null, { status: 502 })
      })
    )

    const authorization = await exports.default.fetch(new Request(authorizeUrl()))
    expect(authorization.status).toBe(200)
    const html = await authorization.text()
    const handle = html.match(/name="handle" value="([^"]+)"/)?.[1]
    expect(handle).toBeTruthy()

    const approval = await exports.default.fetch(
      new Request(`${MCP_ORIGIN}/authorize`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Cookie: cookiesFrom(authorization)
        },
        body: new URLSearchParams({ handle: handle!, scopes: 'user:read' }).toString(),
        redirect: 'manual'
      })
    )
    expect(approval.status).toBe(302)
    const upstreamState = new URL(approval.headers.get('location')!).searchParams.get('state')
    expect(upstreamState).toBeTruthy()

    useCloudflareAuthSuccess()
    const callback = await exports.default.fetch(
      new Request(
        `${MCP_ORIGIN}/oauth/callback?code=authcode&state=${encodeURIComponent(upstreamState!)}`,
        { headers: { Cookie: cookiesFrom(approval) }, redirect: 'manual' }
      )
    )

    expect(metadataFetches).toBe(3)
    expect(callback.status).toBe(500)
    expect(callback.headers.get('location')).toBeNull()
    expect(callback.headers.get('retry-after')).toBeNull()
    expect(await callback.text()).toContain('Restart authorization from your MCP client')
    // The upstream transaction was consumed at the callback.
    expect((await env.OAUTH_KV.list({ prefix: 'transaction:' })).keys).toHaveLength(0)
    expect((await env.OAUTH_KV.list({ prefix: 'grant:' })).keys).toHaveLength(0)
    expect((await env.OAUTH_KV.list({ prefix: 'client:' })).keys).toHaveLength(0)
  })
})

import {
  ExternalTokenError,
  type ResolveExternalTokenInput,
  type ResolveExternalTokenResult
} from '@cloudflare/workers-oauth-provider'

import {
  CloudflareIdentitySchema,
  resolveCloudflareCredential,
  type CloudflareIdentity,
  type CloudflareTokenOwner
} from './cloudflare-identity'
import { AUTH_PROPS_VERSION, type AuthProps } from './types'
import { OAuthError } from './workers-oauth-utils'

const API_TOKEN_IDENTITY_CACHE_TTL_SECONDS = 2_592_000

/** Prefixes are ownership hints; unprefixed legacy credentials remain supported. */
export function cloudflareTokenOwner(token: string): CloudflareTokenOwner {
  if (token.startsWith('cfat_')) return 'account'
  if (token.startsWith('cfut_') || token.startsWith('cfoat_')) return 'user'
  return 'unknown'
}

async function hashApiToken(token: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token))
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

async function getCachedIdentity(
  token: string,
  tokenOwner: CloudflareTokenOwner,
  kv: KVNamespace
): Promise<CloudflareIdentity> {
  const cacheKey = `api-token-identity:v4:${await hashApiToken(token)}`

  try {
    const cachedValue = await kv.get(cacheKey, 'json')
    if (cachedValue !== null) {
      const cached = CloudflareIdentitySchema.safeParse(cachedValue)
      if (cached.success) return cached.data
      console.warn('api_token_identity_probe ignored invalid cache entry')
    }
  } catch (error) {
    console.warn('api_token_identity_probe kv-cache read failed', error)
  }

  const identity = await resolveCloudflareCredential(token, tokenOwner)

  try {
    await kv.put(cacheKey, JSON.stringify(identity), {
      expirationTtl: API_TOKEN_IDENTITY_CACHE_TTL_SECONDS
    })
  } catch (error) {
    console.warn('api_token_identity_probe kv-cache write failed', error)
  }

  return identity
}

function externalTokenError(
  error: OAuthError,
  tokenOwner: CloudflareTokenOwner
): ExternalTokenError {
  const common = { description: error.description, headers: error.headers }

  switch (error.code) {
    case 'invalid_token':
      return new ExternalTokenError('invalid_token', { ...common, statusCode: 401 })
    case 'insufficient_scope':
      return new ExternalTokenError('insufficient_scope', {
        ...common,
        statusCode: 403,
        requiredScopes: tokenOwner === 'account' ? ['account:read'] : ['user:read', 'account:read']
      })
    case 'temporarily_unavailable':
      return new ExternalTokenError('temporarily_unavailable', {
        ...common,
        statusCode: error.statusCode
      })
    case 'server_error':
      return new ExternalTokenError('server_error', {
        ...common,
        statusCode: error.statusCode
      })
    default:
      return new ExternalTokenError(error.statusCode >= 500 ? 'server_error' : 'invalid_token', {
        ...common,
        statusCode: error.statusCode >= 500 ? 502 : 401
      })
  }
}

/** Convert a verified Cloudflare identity into request-local tool props. */
export function buildAuthProps(token: string, identity: CloudflareIdentity): AuthProps {
  switch (identity.type) {
    case 'account':
      return {
        type: 'account_token',
        accessToken: token,
        account: identity.account
      }
    case 'user':
      return {
        type: 'user_token',
        accessToken: token,
        user: identity.user,
        accounts: identity.accounts,
        accountCount: identity.accountCount,
        version: AUTH_PROPS_VERSION
      }
  }
}

/** Resolve direct Cloudflare credentials after the provider's internal token lookup misses. */
export async function resolveExternalToken({
  token,
  env
}: ResolveExternalTokenInput<Env>): Promise<ResolveExternalTokenResult> {
  const tokenOwner = cloudflareTokenOwner(token)
  try {
    const identity = await getCachedIdentity(token, tokenOwner, env.OAUTH_KV)
    return {
      props: buildAuthProps(token, identity),
      // Cloudflare API tokens are opaque credentials, so successful identity
      // validation establishes their local protected-resource audience.
      audience: env.MCP_RESOURCE
    }
  } catch (error) {
    if (error instanceof OAuthError) throw externalTokenError(error, tokenOwner)
    throw error
  }
}

