import { env, exports } from 'cloudflare:workers'
import { afterEach, describe, expect, it } from 'vitest'
import { clearKv } from '../helpers/kv'

const MCP_ORIGIN = 'https://mcp.cloudflare.com'
const DOWNSTREAM_CODE_CHALLENGE = 'I4fhllfHqqQsgap17V2SDI0scSei8H7U0e0rZBDIcbo'

// What some Cursor versions register (seen in production): a private-use callback next to
// https and loopback ones. Cursor signs in with the loopback (or the https) one.
const CURSOR_REDIRECT_URIS = [
  'cursor://anysphere.cursor-mcp/oauth/callback',
  'https://www.cursor.com/agents/mcp/oauth/callback',
  'http://localhost:8787/callback'
]

function register(redirectUris: string[]): Promise<Response> {
  return exports.default.fetch(
    new Request(`${MCP_ORIGIN}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        client_name: 'Cursor',
        redirect_uris: redirectUris,
        grant_types: ['authorization_code', 'refresh_token'],
        response_types: ['code'],
        token_endpoint_auth_method: 'none'
      })
    })
  )
}

function authorize(clientId: string, redirectUri: string): Promise<Response> {
  const url = new URL(`${MCP_ORIGIN}/authorize`)
  url.search = new URLSearchParams({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: redirectUri,
    resource: `${MCP_ORIGIN}/mcp`,
    scope: 'user:read',
    state: 'client-state',
    code_challenge: DOWNSTREAM_CODE_CHALLENGE,
    code_challenge_method: 'S256'
  }).toString()
  return exports.default.fetch(new Request(url), { redirect: 'manual' })
}

describe('Cursor registrations with a cursor:// callback', () => {
  afterEach(async () => {
    await clearKv(env.OAUTH_KV)
  })

  it("accepts Cursor's registration and signs in through its loopback callback", async () => {
    const registration = await register(CURSOR_REDIRECT_URIS)
    expect(registration.status).toBe(201)
    const { client_id: clientId } = (await registration.json()) as { client_id: string }

    const consent = await authorize(clientId, 'http://localhost:8787/callback')
    expect(consent.status).toBe(200)
    expect(await consent.text()).toContain('name="handle"')
  })

  it('still refuses an authorization that uses the private-use callback, without redirecting', async () => {
    const registration = await register(CURSOR_REDIRECT_URIS)
    const { client_id: clientId } = (await registration.json()) as { client_id: string }

    const refused = await authorize(clientId, 'cursor://anysphere.cursor-mcp/oauth/callback')
    expect(refused.status).toBe(400)
    expect(refused.headers.get('location')).toBeNull()
    // workers-oauth-provider holds the URI each request uses to https or loopback http.
    expect(await refused.text()).toContain('Invalid redirect URI')
    expect((await env.OAUTH_KV.list({ prefix: 'grant:' })).keys).toHaveLength(0)
  })

  it('still refuses a registration with a remote http callback', async () => {
    const registration = await register(['http://remote.example/callback'])
    expect(registration.status).toBe(400)
    await expect(registration.json()).resolves.toMatchObject({ error: 'invalid_client_metadata' })
  })
})

import { describe, expect, it } from 'vitest'
import {
  autoResolvedAccountId,
  missingAccountMessage,
  unknownAccountHint
} from '../../src/auth/account-access'
import { AUTH_PROPS_VERSION, LEGACY_ACCOUNTS_PAGE_SIZE, type AuthProps } from '../../src/auth/types'

const accountToken: AuthProps = {
  type: 'account_token',
  accessToken: 't',
  account: { id: 'acct-pinned', name: 'Pinned' }
}

function userToken(overrides: Partial<Extract<AuthProps, { type: 'user_token' }>>): AuthProps {
  return {
    type: 'user_token',
    accessToken: 't',
    user: { id: 'u1', email: 'u@example.com' },
    accounts: [],
    ...overrides
  }
}

function accountList(n: number) {
  return Array.from({ length: n }, (_, i) => ({ id: `acct-${i + 1}`, name: `Account ${i + 1}` }))
}

describe('autoResolvedAccountId', () => {
  it('resolves an account token to its pinned account', () => {
    expect(autoResolvedAccountId(accountToken)).toBe('acct-pinned')
  })

  it('resolves a single-account user token to its only account', () => {
    expect(autoResolvedAccountId(userToken({ accounts: accountList(1) }))).toBe('acct-1')
  })

  it('does not resolve a multi-account user token', () => {
    expect(autoResolvedAccountId(userToken({ accounts: accountList(2) }))).toBeUndefined()
  })

  it('does not resolve a user token whose account list was omitted', () => {
    expect(autoResolvedAccountId(userToken({ accounts: [], accountCount: 137 }))).toBeUndefined()
  })

  it('does not resolve missing props', () => {
    expect(autoResolvedAccountId(undefined)).toBeUndefined()
  })
})

describe('missingAccountMessage', () => {
  const guidance = 'Call GET /accounts to discover available accounts.'

  it('lists a complete account list so the model can pick one', () => {
    const message = missingAccountMessage(
      userToken({ accounts: accountList(2), version: AUTH_PROPS_VERSION }),
      guidance
    )
    expect(message).toBe(
      "No account selected. Pass account_id with one of this session's accounts:\n- acct-1 (Account 1)\n- acct-2 (Account 2)"
    )
  })

  it('reports the count and discovery guidance when the list was omitted', () => {
    expect(missingAccountMessage(userToken({ accounts: [], accountCount: 137 }), guidance)).toBe(
      `No account selected: this token has access to 137 accounts. ${guidance}`
    )
  })

  it('does not list a legacy list that was probably truncated', () => {
    const message = missingAccountMessage(
      userToken({ accounts: accountList(LEGACY_ACCOUNTS_PAGE_SIZE) }),
      guidance
    )
    expect(message).toBe(
      `No account selected: this token has access to multiple accounts. ${guidance}`
    )
  })

  it('says so when the session has no accounts', () => {
    expect(missingAccountMessage(userToken({ accounts: [] }), guidance)).toBe(
      'No account selected: no Cloudflare accounts are authorized for this session.'
    )
  })
})

describe('unknownAccountHint', () => {
  const multiAccount = userToken({ accounts: accountList(2), version: AUTH_PROPS_VERSION })

  it("lists the session's accounts when account_id isn't one of them", () => {
    expect(unknownAccountHint(multiAccount, 'acct-typo')).toBe(
      "account_id acct-typo is not one of this session's accounts:\n- acct-1 (Account 1)\n- acct-2 (Account 2)"
    )
  })

  it("is empty when account_id is one of the session's accounts", () => {
    expect(unknownAccountHint(multiAccount, 'acct-2')).toBe('')
  })

  it("names an account token's own account when given another", () => {
    expect(unknownAccountHint(accountToken, 'acct-other')).toBe(
      "account_id acct-other is not this token's account. This token is scoped to acct-pinned (Pinned); omit account_id to use it."
    )
    expect(unknownAccountHint(accountToken, 'acct-pinned')).toBe('')
  })

  it('is empty when the account list is not known', () => {
    expect(unknownAccountHint(userToken({ accounts: [], accountCount: 137 }), 'acct-x')).toBe('')
    expect(
      unknownAccountHint(userToken({ accounts: accountList(LEGACY_ACCOUNTS_PAGE_SIZE) }), 'acct-x')
    ).toBe('')
  })
})

import { exports } from 'cloudflare:workers'
import { http, HttpResponse } from 'msw'
import { server } from '../setup/msw'
import { cfAccountsSuccess, cfSuccess } from './cloudflare-api'

const ORIGIN = 'https://mcp.cloudflare.com'
const RESOURCE = `${ORIGIN}/mcp`
const REDIRECT_URI = 'https://app.example.com/cb'
const CODE_VERIFIER = 'test-downstream-code-verifier'
const CODE_CHALLENGE = 'I4fhllfHqqQsgap17V2SDI0scSei8H7U0e0rZBDIcbo'

function cookies(response: Response): string {
  return response.headers
    .getSetCookie()
    .map((cookie) => cookie.split(';')[0])
    .join('; ')
}

function required<T>(value: T | null | undefined, what: string): T {
  if (value === null || value === undefined) throw new Error(`OAuth test flow: no ${what}`)
  return value
}

/**
 * Connect through the real OAuth flow and return the MCP access token.
 *
 * Cloudflare's token endpoint is mocked to grant exactly `scopes`, and the
 * identity probes return one user with one account.
 *
 * @param scopes - The scopes to request at consent and have Cloudflare grant.
 * @param account - The account the identity probe returns.
 * @param resource - The RFC 8707 resource the client names at /authorize and /token.
 * @returns A provider-issued MCP access token.
 */
export async function connectWithOAuth(
  scopes: readonly string[],
  account = { id: 'acc-1', name: 'Account One' },
  resource = RESOURCE
): Promise<string> {
  const scope = scopes.join(' ')
  server.use(
    http.post('https://dash.cloudflare.com/oauth2/token', () =>
      HttpResponse.json({
        access_token: 'upstream-access-token',
        expires_in: 3600,
        refresh_token: 'upstream-refresh-token',
        scope,
        token_type: 'bearer'
      })
    ),
    http.get('https://api.cloudflare.com/client/v4/user', () =>
      HttpResponse.json(cfSuccess({ id: 'user-1', email: 'user@example.com' }))
    ),
    http.get('https://api.cloudflare.com/client/v4/accounts', () =>
      HttpResponse.json(cfAccountsSuccess([account]))
    )
  )

  const registered = await exports.default.fetch(
    new Request(`${ORIGIN}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ redirect_uris: [REDIRECT_URI], token_endpoint_auth_method: 'none' })
    })
  )
  const { client_id: clientId } = (await registered.json()) as { client_id: string }

  const authorize = new URL(`${ORIGIN}/authorize`)
  for (const [key, value] of Object.entries({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: REDIRECT_URI,
    resource,
    scope,
    code_challenge: CODE_CHALLENGE,
    code_challenge_method: 'S256'
  })) {
    authorize.searchParams.set(key, value)
  }
  const consentPage = await exports.default.fetch(new Request(authorize))
  const html = await consentPage.text()
  const handle = required(html.match(/name="handle" value="([^"]+)"/)?.[1], 'consent handle')

  const approved = await exports.default.fetch(
    new Request(`${ORIGIN}/authorize`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Cookie: cookies(consentPage)
      },
      body: new URLSearchParams([
        ['handle', handle],
        ...scopes.map((s) => ['scopes', s])
      ]).toString(),
      redirect: 'manual'
    })
  )
  const state = required(
    new URL(required(approved.headers.get('location'), 'upstream redirect')).searchParams.get(
      'state'
    ),
    'state'
  )

  const callback = await exports.default.fetch(
    new Request(`${ORIGIN}/oauth/callback?code=authcode&state=${encodeURIComponent(state)}`, {
      headers: { Cookie: cookies(approved) },
      redirect: 'manual'
    })
  )
  const code = required(
    new URL(required(callback.headers.get('location'), 'client redirect')).searchParams.get('code'),
    'authorization code'
  )

  const token = await exports.default.fetch(
    new Request(`${ORIGIN}/token`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        client_id: clientId,
        redirect_uri: REDIRECT_URI,
        code_verifier: CODE_VERIFIER,
        resource
      }).toString()
    })
  )
  return ((await token.json()) as { access_token: string }).access_token
}

import { env, exports } from 'cloudflare:workers'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { describeRedirectUri } from '../../src/auth/registration-log'
import { clearKv } from '../helpers/kv'

const MCP_ORIGIN = 'https://mcp.cloudflare.com'

function register(metadata: Record<string, unknown>): Promise<Response> {
  return exports.default.fetch(
    new Request(`${MCP_ORIGIN}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'User-Agent': 'Cursor/1.0.0' },
      body: JSON.stringify(metadata)
    })
  )
}

/** The `dcr_refused` lines among everything passed to console.warn. */
function refusalLogs(calls: readonly unknown[][]): Record<string, unknown>[] {
  const entries: Record<string, unknown>[] = []
  for (const [line] of calls) {
    if (typeof line !== 'string' || !line.startsWith('{')) continue
    const entry: unknown = JSON.parse(line)
    if (
      typeof entry === 'object' &&
      entry !== null &&
      'event' in entry &&
      entry.event === 'dcr_refused'
    ) {
      entries.push(entry as Record<string, unknown>)
    }
  }
  return entries
}

describe('refused registration diagnostics', () => {
  afterEach(async () => {
    vi.restoreAllMocks()
    await clearKv(env.OAUTH_KV)
  })

  it('logs what a refused client asked for, without queries or credentials', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})

    const response = await register({
      client_name: 'Agent host',
      redirect_uris: ['grokbot://mcp/oauth/callback', 'http://user:pw@remote.example/cb?code=x#f'],
      token_endpoint_auth_method: 'none'
    })

    expect(response.status).toBe(400)
    // The client still gets the provider's error; the log reads a copy.
    expect(await response.json()).toMatchObject({ error: 'invalid_client_metadata' })
    await vi.waitFor(() => expect(refusalLogs(warn.mock.calls)).toHaveLength(1))
    expect(refusalLogs(warn.mock.calls)[0]).toMatchObject({
      status: 400,
      error: 'invalid_client_metadata',
      userAgent: 'Cursor/1.0.0',
      clientName: 'Agent host',
      redirectUris: ['grokbot://mcp/oauth/callback', 'http://remote.example/cb'],
      redirectUriCount: 2
    })
  })

  it('logs nothing for a registration it accepts', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})

    const response = await register({
      client_name: 'Loopback client',
      redirect_uris: ['http://localhost:8787/callback'],
      token_endpoint_auth_method: 'none'
    })

    expect(response.status).toBe(201)
    await response.body?.cancel()
    await new Promise((resolve) => setTimeout(resolve, 50))
    expect(refusalLogs(warn.mock.calls)).toHaveLength(0)
  })

  it('keeps only the scheme of a redirect URI it cannot parse', () => {
    expect(describeRedirectUri('not a url')).toBe('(unparseable, scheme none)')
    expect(describeRedirectUri(42)).toBe('(not a string)')
  })
})

import { describe, expect, it } from 'vitest'

import { REQUIRED_SCOPES, SCOPE_DEFINITIONS, SCOPE_TEMPLATES } from '../../src/auth/scopes'
import {
  renderApprovalDialog,
  renderErrorPage,
  type ApprovalDialogOptions
} from '../../src/auth/workers-oauth-utils'

function render(options: Partial<ApprovalDialogOptions> = {}): Promise<string> {
  const response = renderApprovalDialog(new Request('https://mcp.cloudflare.com/authorize'), {
    consent: {
      clientId: 'opaque-client-id',
      clientName: 'Test client',
      redirectUri: 'https://callback.example/oauth/callback',
      redirectHost: 'callback.example',
      redirectIsLoopback: false,
      scope: []
    },
    server: { name: 'Cloudflare API MCP' },
    handle: 'test-consent-handle',
    headers: new Headers({ 'Set-Cookie': '__Host-oauth-consent-0123456789abcdef=test' }),
    scopeTemplates: {},
    scopeDefinitions: {},
    requiredScopes: [],
    initialScopes: [],
    ...options
  })

  return response.text()
}

/**
 * Text inside `<main>` as a person reads it, with whitespace collapsed. The
 * page's script and styles sit outside `<main>`, so skipping everything
 * between `<` and `>` leaves only the visible text.
 */
function visibleText(html: string): string {
  const main = html.slice(html.indexOf('<main'), html.indexOf('</main>'))
  let text = ''
  let inTag = false
  for (const char of main) {
    if (char === '<') inTag = true
    else if (char === '>') inTag = false
    else if (!inTag) text += char
  }
  return text.replace(/\s+/g, ' ')
}

describe('OAuth page colour scheme', () => {
  // Cloudflare's authorization screen, which follows the consent page, is always light.
  it('renders the consent page in light mode regardless of the system preference', async () => {
    const body = await render()
    expect(body).toContain('color-scheme: light;')
    expect(body).not.toContain('color-scheme: light dark')
  })

  it('renders the error page in light mode regardless of the system preference', async () => {
    const body = await renderErrorPage('Server Error', 'Try again.').text()
    expect(body).toContain('color-scheme: light;')
    expect(body).not.toContain('color-scheme: light dark')
  })
})

describe('OAuth approval dialog identity details', () => {
  it('posts back only the consent handle, escaped, with an Allow and a Deny', async () => {
    const body = await render({ handle: 'handle"><script>' })
    expect(body).toContain('name="handle" value="handle&quot;&gt;&lt;script&gt;"')
    expect(body).not.toContain('name="state"')
    expect(body).not.toContain('name="csrf_token"')
    expect(body).toContain('name="decision" value="deny"')
    expect(body).toContain('name="decision" value="approve"')
  })

  it('shows the full CIMD client ID and redirect URLs without credentials', async () => {
    const body = await render({
      consent: {
        clientId: 'https://identity.example/oauth/client.json?sensitive=client-query',
        clientDomain: 'identity.example',
        clientName: 'CIMD client',
        redirectUri: 'https://user@callback.example:8443/oauth/callback?sensitive=redirect-query',
        redirectHost: 'callback.example',
        redirectIsLoopback: false,
        scope: []
      }
    })

    const text = visibleText(body)
    expect(text).toContain(
      'Client ID https://identity.example/oauth/client.json?sensitive=client-query'
    )
    expect(text).toContain(
      'Redirect URI https://callback.example:8443/oauth/callback?sensitive=redirect-query'
    )
    expect(text).not.toContain('Local redirect:')
    expect(body).not.toContain('user@')
  })

  it('does not present a registered client ID as a trusted identity', async () => {
    // describeConsent() sets clientDomain only for a Client ID Metadata Document client.
    const body = await render({
      consent: {
        clientId: 'http://untrusted.example/client.json',
        clientName: '<img src=x onerror=alert(1)>',
        redirectUri: 'https://callback.example/oauth/callback',
        redirectHost: 'callback.example',
        redirectIsLoopback: false,
        scope: []
      }
    })

    const text = visibleText(body)
    expect(text).not.toContain('Client ID')
    expect(body).not.toContain('untrusted.example')
    expect(body).not.toContain('<img src=x onerror=alert(1)>')
    expect(body).toContain('&lt;img src=x onerror=alert(1)&gt;')
    expect(text).toContain('Redirect URI https://callback.example/oauth/callback')
  })

  it('warns when a native client redirects to a loopback listener', async () => {
    const body = await render({
      consent: {
        clientId: 'https://client.example/oauth/client.json',
        clientDomain: 'client.example',
        clientName: 'Native client',
        redirectUri: 'http://localhost:3210/callback',
        redirectHost: 'localhost',
        redirectIsLoopback: true,
        scope: []
      }
    })

    const text = visibleText(body)
    expect(text).toContain('Redirect URI http://localhost:3210/callback')
    expect(text).toContain(
      'Local redirect: this client will receive the authorization code on this device.'
    )
  })
})

describe('OAuth approval dialog templates', () => {
  const templates = {
    scopeTemplates: SCOPE_TEMPLATES,
    scopeDefinitions: SCOPE_DEFINITIONS,
    requiredScopes: REQUIRED_SCOPES
  }

  it('lists the scopes a client asked for when they match no template', async () => {
    const body = await render({
      ...templates,
