import { env } from 'cloudflare:workers'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { withRefreshAdmission } from '../../src/auth/refresh-admission-gate'
import { OAuthError } from '../../src/auth/workers-oauth-utils'
import { clearKv } from '../helpers/kv'

let grantSequence = 0

function grant() {
  return { userId: 'user-1', grantId: `grant-${++grantSequence}` }
}

afterEach(async () => {
  vi.restoreAllMocks()
  await clearKv(env.OAUTH_KV)
})

describe('withRefreshAdmission', () => {
  it('allows different grants to proceed independently', async () => {
    const refresh = vi.fn(async (value: string) => value)

    const results = await Promise.all([
      withRefreshAdmission(env.OAUTH_KV, grant(), () => refresh('first')),
      withRefreshAdmission(env.OAUTH_KV, grant(), () => refresh('second'))
    ])

    expect(results).toEqual(['first', 'second'])
    expect(refresh).toHaveBeenCalledTimes(2)
  })

  it('ignores malformed external KV state and replaces it with a valid claim', async () => {
    const identity = grant()
    await env.OAUTH_KV.put(
      `oauth:refresh-admission:v1:${identity.userId}:${identity.grantId}`,
      JSON.stringify({ owner: 42, blockedUntil: 'never' })
    )

    await expect(
      withRefreshAdmission(env.OAUTH_KV, identity, async () => 'refreshed')
    ).resolves.toBe('refreshed')
  })

  it('fails closed when a KV claim cannot be written', async () => {
    vi.spyOn(env.OAUTH_KV, 'put').mockRejectedValueOnce(new Error('KV unavailable'))

    await expect(
      withRefreshAdmission(env.OAUTH_KV, grant(), async () => 'must not run')
    ).rejects.toMatchObject({
      code: 'temporarily_unavailable',
      statusCode: 429,
      headers: { 'Retry-After': '30' }
    })
  })

  it('releases admission after any callback error', async () => {
    const identity = grant()

    await expect(
      withRefreshAdmission(env.OAUTH_KV, identity, async () => {
        throw new OAuthError('invalid_grant', 'dead token', 400)
      })
    ).rejects.toMatchObject({ code: 'invalid_grant' })

    await expect(
      withRefreshAdmission(env.OAUTH_KV, identity, async () => 'retry succeeded')
    ).resolves.toBe('retry succeeded')
  })
})

import { GrantType, OAuthError as ProviderOAuthError } from '@cloudflare/workers-oauth-provider'
import { env } from 'cloudflare:workers'
import { http, HttpResponse } from 'msw'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { handleTokenExchangeCallback } from '../../src/auth/oauth-handler'
import { OAuthError } from '../../src/auth/workers-oauth-utils'
import { clearKv } from '../helpers/kv'
import { server } from '../setup/msw'

let grantId: string
let grantSequence = 0

function refreshCallback(refreshToken = 'old-refresh-token') {
  return handleTokenExchangeCallback(
    {
      grantType: GrantType.REFRESH_TOKEN,
      clientId: 'mcp-client',
      subjectClientId: 'mcp-client',
      userId: 'user-1',
      grantId,
      scope: ['read', 'write'],
      requestedScope: ['read', 'write'],
      resource: 'https://mcp.cloudflare.com/mcp',
      env,
      props: {
        type: 'user_token',
        accessToken: 'old-access-token',
        user: { id: 'user-1', email: 'user@example.com' },
        accounts: [{ id: 'account-1', name: 'Account 1' }],
        refreshToken
      }
    },
    'client-id',
    'client-secret'
  )
}

const expectedRefreshResult = {
  newProps: {
    type: 'user_token',
    accessToken: 'new-access-token',
    user: { id: 'user-1', email: 'user@example.com' },
    accounts: [{ id: 'account-1', name: 'Account 1' }],
    refreshToken: 'new-refresh-token'
  },
  accessTokenTTL: 1234,
  // The upstream refresh granted `read` only (scope: 'read' below): the MCP token follows it.
  accessTokenScope: ['read']
}

const OAUTH_TOKEN_URL = 'https://dash.cloudflare.com/oauth2/token'

beforeEach(() => {
  grantId = `grant-${++grantSequence}`
})

afterEach(async () => {
  vi.restoreAllMocks()
  await clearKv(env.OAUTH_KV)
})

describe('handleTokenExchangeCallback', () => {
  it('refreshes upstream tokens and returns updated auth props', async () => {
    let form: FormData | undefined
    server.use(
      http.post(OAUTH_TOKEN_URL, async ({ request }) => {
        form = await request.formData()
        return HttpResponse.json({
          access_token: 'new-access-token',
          refresh_token: 'new-refresh-token',
          expires_in: 1234,
          scope: 'read',
          token_type: 'bearer'
        })
      })
    )

    await expect(refreshCallback()).resolves.toEqual(expectedRefreshResult)
    expect(form?.get('grant_type')).toBe('refresh_token')
    expect(form?.get('refresh_token')).toBe('old-refresh-token')
  })

  it('admits one concurrent refresh per grant and rejects competitors as retryable', async () => {
    let calls = 0
    server.use(
      http.post(OAUTH_TOKEN_URL, async ({ request }) => {
        calls++
        const form = await request.formData()
        expect(form.get('refresh_token')).toBe('old-refresh-token')
        await new Promise((resolve) => setTimeout(resolve, 50))
        return HttpResponse.json({
          access_token: 'new-access-token',
          refresh_token: 'new-refresh-token',
          expires_in: 1234,
          scope: 'read',
          token_type: 'bearer'
        })
      })
    )

    const results = await Promise.allSettled(Array.from({ length: 10 }, () => refreshCallback()))
    const fulfilled = results.filter((result) => result.status === 'fulfilled')
    const rejected = results.filter((result) => result.status === 'rejected')

    expect(calls).toBe(1)
    expect(fulfilled).toEqual([{ status: 'fulfilled', value: expectedRefreshResult }])
    expect(rejected).toHaveLength(9)
    for (const result of rejected) {
      expect(result.reason).toMatchObject({
        code: 'temporarily_unavailable',
        statusCode: 429,
        headers: { 'Retry-After': expect.any(String) }
      })
    }
  })

  it('retains a successful admission tombstone for immediate grant retries', async () => {
    server.use(
      http.post(OAUTH_TOKEN_URL, () =>
        HttpResponse.json({
          access_token: 'new-access-token',
          refresh_token: 'new-refresh-token',
          expires_in: 1234,
          scope: 'read',
          token_type: 'bearer'
        })
      )
    )

    await expect(refreshCallback()).resolves.toEqual(expectedRefreshResult)
    await expect(refreshCallback()).rejects.toMatchObject({
      code: 'temporarily_unavailable',
      statusCode: 429
    })
  })

  it('releases admission after a transient upstream failure', async () => {
    let calls = 0
    server.use(
      http.post(OAUTH_TOKEN_URL, () => {
        calls++
        if (calls === 1) {
          return HttpResponse.text('rate limited', {
            status: 429,
            headers: { 'Retry-After': '1' }
          })
        }
        return HttpResponse.json({
          access_token: 'new-access-token',
          refresh_token: 'new-refresh-token',
          expires_in: 1234,
          scope: 'read',
          token_type: 'bearer'
        })
      })
    )

    await expect(refreshCallback()).rejects.toMatchObject({
      code: 'temporarily_unavailable',
      statusCode: 429
    })
    await expect(refreshCallback()).resolves.toEqual(expectedRefreshResult)
    expect(calls).toBe(2)
  })

  it('narrows the MCP access token to the scopes the upstream refresh granted', async () => {
    server.use(
      http.post(OAUTH_TOKEN_URL, () =>
        HttpResponse.json({
          access_token: 'new-access-token',
          refresh_token: 'new-refresh-token',
          expires_in: 1234,
          scope: 'write unrelated',
          token_type: 'bearer'
        })
      )
    )
    await expect(refreshCallback()).resolves.toMatchObject({ accessTokenScope: ['write'] })
  })

  it('throws the provider OAuthError invalid_grant for a dead upstream grant, which the provider revokes', async () => {
    server.use(
      http.post(OAUTH_TOKEN_URL, () => HttpResponse.text('invalid grant', { status: 400 }))
    )

    // workers-oauth-provider 1.x revokes the grant for any invalid_grant thrown here
    // (covered end to end in oauth-routes.test.ts), so the callback only has to throw it.
    const error = await refreshCallback('old-refresh-token').catch((thrown: unknown) => thrown)
    expect(error).toBeInstanceOf(ProviderOAuthError)
    expect(error).toMatchObject({ name: 'OAuthError', code: 'invalid_grant', statusCode: 400 })
  })

  it('throws temporarily_unavailable for transient upstream failures, which keeps the grant', async () => {
    server.use(
      http.post(OAUTH_TOKEN_URL, () =>
        HttpResponse.text('rate limited', { status: 429, headers: { 'Retry-After': '17' } })
      )
    )

    await expect(refreshCallback('old-refresh-token')).rejects.toMatchObject({
      code: 'temporarily_unavailable',
      statusCode: 429,
      headers: { 'Retry-After': '17' }
    })
  })

  it('returns the provider-compatible OAuth error from upstream', async () => {
    server.use(
      http.post(OAUTH_TOKEN_URL, () =>
        HttpResponse.text('rate limited', { status: 429, headers: { 'Retry-After': '17' } })
      )
    )

    try {
      await refreshCallback()
      throw new Error('Expected refresh to fail')
    } catch (error) {
      expect(error).toBeInstanceOf(OAuthError)
      expect(error).toBeInstanceOf(ProviderOAuthError)
    }
  })

  it('lets non-OAuth thrown errors propagate', async () => {
    server.use(http.post(OAUTH_TOKEN_URL, () => HttpResponse.json({ not: 'a token' })))

    await expect(refreshCallback()).rejects.not.toBeInstanceOf(OAuthError)
  })
})

import { http, HttpResponse } from 'msw'
import { describe, expect, it } from 'vitest'

import {
  generatePKCECodes,
  getAuthorizationURL,
  getAuthToken,
  refreshAuthToken
} from '../../src/auth/cloudflare-auth'
import { OAuthError } from '../../src/auth/workers-oauth-utils'
import { server } from '../setup/msw'

const OAUTH_DOMAIN = 'https://dash.cloudflare.com'
const OAUTH_TOKEN_URL = `${OAUTH_DOMAIN}/oauth2/token`

const refreshParams = {
  client_id: 'client-id',
  client_secret: 'client-secret',
  refresh_token: 'refresh-token',
  oauthDomain: OAUTH_DOMAIN
}

const tokenParams = {
  client_id: 'client-id',
  client_secret: 'client-secret',
  redirect_uri: 'https://mcp.example.com/oauth/callback',
  code: 'auth-code',
  code_verifier: 'verifier',
  oauthDomain: OAUTH_DOMAIN
}

const validToken = {
  access_token: 'access-token',
  expires_in: 3600,
  refresh_token: 'refresh-token',
  scope: 'read',
  token_type: 'bearer'
}

/** Run the REAL refreshAuthToken against an MSW-mocked upstream `response`. */
async function expectRefreshOAuthError(response: Response): Promise<OAuthError> {
  server.use(http.post(OAUTH_TOKEN_URL, () => response))

  try {
    await refreshAuthToken(refreshParams)
    throw new Error('Expected refreshAuthToken to throw')
  } catch (error) {
    expect(error).toBeInstanceOf(OAuthError)
    return error as OAuthError
  }
}

/** Run the REAL getAuthToken against an MSW-mocked upstream `response`. */
async function expectAuthTokenOAuthError(response: Response): Promise<OAuthError> {
  server.use(http.post(OAUTH_TOKEN_URL, () => response))

  try {
    await getAuthToken(tokenParams)
    throw new Error('Expected getAuthToken to throw')
  } catch (error) {
    expect(error).toBeInstanceOf(OAuthError)
    return error as OAuthError
  }
}

/** Recompute the expected S256 challenge for a verifier, base64url-encoded. */
async function s256Challenge(verifier: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier))
  let binary = ''
  for (const byte of new Uint8Array(digest)) binary += String.fromCharCode(byte)
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '')
}

describe('generatePKCECodes', () => {
  it('produces a url-safe verifier and a matching S256 challenge', async () => {
    const { codeVerifier, codeChallenge } = await generatePKCECodes()

    // Verifier is base64url (no +, /, or = padding).
    expect(codeVerifier).toMatch(/^[A-Za-z0-9\-._~]+$/)
    expect(codeVerifier.length).toBeGreaterThanOrEqual(43)
    // Challenge == base64url(SHA-256(verifier)).
    expect(codeChallenge).toBe(await s256Challenge(codeVerifier))
    expect(codeChallenge).not.toContain('=')
  })

  it('generates a fresh verifier each call', async () => {
    const a = await generatePKCECodes()
    const b = await generatePKCECodes()
    expect(a.codeVerifier).not.toBe(b.codeVerifier)
    expect(a.codeChallenge).not.toBe(b.codeChallenge)
  })
})

describe('getAuthorizationURL', () => {
  it('builds the Cloudflare /oauth2/auth URL with S256 PKCE and an opaque state token', async () => {
    const stateToken = 'b9f1c0de-1234-4abc-9def-0123456789ab'
    const { authUrl } = await getAuthorizationURL({
      client_id: 'client-id',
      redirect_uri: 'https://mcp.example.com/oauth/callback',
      stateToken,
      scopes: ['user:read', 'account:read'],
      codeChallenge: 'challenge-123',
      oauthDomain: OAUTH_DOMAIN
    })

    const url = new URL(authUrl)
    expect(url.origin + url.pathname).toBe(`${OAUTH_DOMAIN}/oauth2/auth`)
    expect(url.searchParams.get('response_type')).toBe('code')
    expect(url.searchParams.get('client_id')).toBe('client-id')
    expect(url.searchParams.get('redirect_uri')).toBe('https://mcp.example.com/oauth/callback')
    expect(url.searchParams.get('code_challenge')).toBe('challenge-123')
    expect(url.searchParams.get('code_challenge_method')).toBe('S256')
    expect(url.searchParams.get('scope')).toBe('user:read account:read')
    // State is the opaque KV lookup token, passed through verbatim (RFC 6749 §10.12).
    expect(url.searchParams.get('state')).toBe(stateToken)
  })
})

describe('getAuthToken', () => {
  it('exchanges an authorization code and parses the token response', async () => {
    let form: FormData | undefined
    let authHeader: string | null = null
    let userAgent: string | null = null
    server.use(
      http.post(OAUTH_TOKEN_URL, async ({ request }) => {
        form = await request.formData()
        authHeader = request.headers.get('Authorization')
        userAgent = request.headers.get('User-Agent')
        return HttpResponse.json(validToken)
      })
    )

    await expect(getAuthToken(tokenParams)).resolves.toEqual(validToken)

    // Sends grant_type=authorization_code with the PKCE verifier + Basic auth.
    expect(form?.get('grant_type')).toBe('authorization_code')
    expect(form?.get('code')).toBe('auth-code')
    expect(form?.get('code_verifier')).toBe('verifier')
    expect(authHeader).toBe(`Basic ${btoa('client-id:client-secret')}`)
    expect(userAgent).toBe('cloudflare-mcp (+https://github.com/cloudflare/mcp)')
  })

  it.each([
    // The RFC 6749 error field decides, not the HTTP status.
    [
      'invalid_grant (JSON)',
      Response.json({ error: 'invalid_grant' }, { status: 400 }),
      'invalid_grant',
      400
    ],
    [
      'invalid_grant (form)',
      new Response('error=invalid_grant', { status: 400 }),
      'invalid_grant',
      400
    ],
    [
      'a 400 with no readable error',
      new Response('bad code', { status: 400 }),
      'invalid_grant',
      400
    ],
    // Our client credentials: a server problem, never invalid_client to the MCP client.
    [
      'invalid_client',
      Response.json({ error: 'invalid_client' }, { status: 401 }),
      'server_error',
      502
    ],
    ['a bare 401', new Response('bad creds', { status: 401 }), 'server_error', 502],
    [
      'unauthorized_client',
      Response.json({ error: 'unauthorized_client' }, { status: 400 }),
      'server_error',
      502
    ],
    // A bug on our side must not revoke users' grants.
    [
      'invalid_request',
      Response.json({ error: 'invalid_request' }, { status: 400 }),
      'server_error',
      502
    ],
    [
      'invalid_scope',
      Response.json({ error: 'invalid_scope' }, { status: 400 }),
      'server_error',
      502
    ],
    // Transient: retryable, the grant is kept.
    ['a 5xx', new Response('boom', { status: 503 }), 'temporarily_unavailable', 503],
    [
      'temporarily_unavailable',
      Response.json({ error: 'temporarily_unavailable' }, { status: 400 }),
      'temporarily_unavailable',
      503
    ]
  ])('maps %s', async (_label, response, code, statusCode) => {
    const error = await expectAuthTokenOAuthError(response)
    expect(error).toMatchObject({ code, statusCode })
  })

  it('throws (non-OAuth) when the token response shape is invalid', async () => {
    server.use(http.post(OAUTH_TOKEN_URL, () => HttpResponse.json({ not: 'a token' })))
    await expect(getAuthToken(tokenParams)).rejects.not.toBeInstanceOf(OAuthError)
  })
})

describe('refreshAuthToken', () => {
  it('sends the cloudflare-mcp User-Agent', async () => {
    let userAgent: string | null = null
    server.use(
      http.post(OAUTH_TOKEN_URL, ({ request }) => {
        userAgent = request.headers.get('User-Agent')
        return HttpResponse.json(validToken)
      })
    )

    await expect(refreshAuthToken(refreshParams)).resolves.toEqual(validToken)
    expect(userAgent).toBe('cloudflare-mcp (+https://github.com/cloudflare/mcp)')
  })

  it('preserves Retry-After from upstream OAuth 429 responses', async () => {
    const error = await expectRefreshOAuthError(
      new Response('rate limited', { status: 429, headers: { 'Retry-After': '42' } })
    )

    expect(error).toMatchObject({
      code: 'temporarily_unavailable',
      statusCode: 429,
      headers: { 'Retry-After': '42' }
    })
  })

  it('defaults Retry-After when upstream OAuth 429 responses omit it', async () => {
    const error = await expectRefreshOAuthError(new Response('rate limited', { status: 429 }))

    expect(error).toMatchObject({
      code: 'temporarily_unavailable',
      statusCode: 429,
      headers: { 'Retry-After': '30' }
    })
  })
})

import { createExecutionContext } from 'cloudflare:test'
import { env, exports } from 'cloudflare:workers'
import { http, HttpResponse } from 'msw'
import * as v0102 from 'workers-oauth-provider-0-10-2'
import * as v110 from 'workers-oauth-provider-1-1-0'
import { afterEach, describe, expect, it } from 'vitest'
import { AUTH_PROPS_VERSION } from '../../src/auth/types'
import { cfAccountsSuccess, cfSuccess } from '../helpers/cloudflare-api'
import { clearKv } from '../helpers/kv'
import { modernMcpRequest, parseMcpResult } from '../helpers/mcp'
import { server } from '../setup/msw'

/**
 * Grants and tokens issued before an upgrade keep working after it. Each case issues them with the
 * real package a deployment ran (0.10.2 in production, 1.1.0 on staging), configured as that
 * deployment was, into the same OAUTH_KV; then the current worker, on the current package, serves
 * the access token, refreshes the grant, and serves the new token.
 */

const MCP_ORIGIN = 'https://mcp.cloudflare.com'
const MCP_RESOURCE = `${MCP_ORIGIN}/mcp`
const REDIRECT_URI = 'https://app.example.com/cb'
const CODE_VERIFIER = 'test-downstream-code-verifier'
const CODE_CHALLENGE = 'I4fhllfHqqQsgap17V2SDI0scSei8H7U0e0rZBDIcbo'

const notFound = { fetch: () => new Response(null, { status: 404 }) }

/** What issuing tokens needs from a legacy release: its provider and two of its helpers. */
interface LegacyDeployment {
  fetch(request: Request): Promise<Response>
  /** parseAuthRequest() then completeAuthorization() with the props that release's callback stored. */
  authorize(authorizeUrl: string): Promise<string>
}

/** The props the /oauth/callback of these releases stored. */
const CALLBACK_PROPS = {
  type: 'user_token',
  user: { id: 'user-1', email: 'user@example.com' },
  accounts: [{ id: 'acc-1', name: 'Account One' }],
  accountCount: 1,
  version: AUTH_PROPS_VERSION,
  accessToken: 'upstream-access-1',
  refreshToken: 'upstream-refresh-1'
}

/** The provider options each release shipped with, minus the handlers issuing tokens doesn't reach. */
const BASE_OPTIONS = {
  apiHandlers: { '/mcp': notFound },
  defaultHandler: notFound,
  authorizeEndpoint: '/authorize',
  tokenEndpoint: '/token',
  clientRegistrationEndpoint: '/register',
  clientIdMetadataDocumentEnabled: true,
  resourceMetadata: { resource: MCP_RESOURCE, resource_name: 'Cloudflare API MCP Server' },
  accessTokenTTL: 3600,
  refreshTokenTTL: 2592000
}

/** Production: 0.10.2, which also matched legacy grants by origin. */
function production0102(): LegacyDeployment {
  const options: v0102.OAuthProviderOptions = { ...BASE_OPTIONS, resourceMatchOriginOnly: true }
  const provider = new v0102.OAuthProvider(options)
  const helpers = v0102.getOAuthApi(options, env)
  const ctx = createExecutionContext()
  return {
    fetch: (request) => provider.fetch(request, env, ctx),
    async authorize(authorizeUrl) {
      const request = await helpers.parseAuthRequest(new Request(authorizeUrl))
      const grant = {
        request,
        userId: 'user-1',
        metadata: { label: 'user@example.com' },
        scope: request.scope
      }
      return (await helpers.completeAuthorization({ ...grant, props: CALLBACK_PROPS })).redirectTo
    }
  }
}

/** Staging: 1.1.0. */
function staging110(): LegacyDeployment {
  const options: v110.OAuthProviderOptions = BASE_OPTIONS
  const provider = new v110.OAuthProvider(options)
  const helpers = v110.getOAuthApi(options, env)
  const ctx = createExecutionContext()
  return {
    fetch: (request) => provider.fetch(request, env, ctx),
    async authorize(authorizeUrl) {
      const request = await helpers.parseAuthRequest(new Request(authorizeUrl))
      const grant = {
        request,
        userId: 'user-1',
        metadata: { label: 'user@example.com' },
        scope: request.scope
      }
      return (await helpers.completeAuthorization({ ...grant, props: CALLBACK_PROPS })).redirectTo
    }
  }
}

const LEGACY_DEPLOYMENTS = [
  { version: '0.10.2 (production)', deploy: production0102 },
  { version: '1.1.0 (staging)', deploy: staging110 }
]

/** Register a client, authorize it and exchange the code, all on the legacy package. */
async function issueWithLegacy(
  legacy: LegacyDeployment,
  resource: string | undefined
): Promise<{ clientId: string; access_token: string; refresh_token: string }> {
  const registration = await legacy.fetch(
    new Request(`${MCP_ORIGIN}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ redirect_uris: [REDIRECT_URI], token_endpoint_auth_method: 'none' })
    })
  )
  expect(registration.status).toBe(201)
  const { client_id: clientId } = (await registration.json()) as { client_id: string }

  const authorize = new URL(`${MCP_ORIGIN}/authorize`)
  authorize.search = new URLSearchParams({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: REDIRECT_URI,
    scope: 'user:read account:read offline_access',
    state: 'client-state',
    code_challenge: CODE_CHALLENGE,
    code_challenge_method: 'S256',
    ...(resource === undefined ? {} : { resource })
  }).toString()
  const code = new URL(await legacy.authorize(authorize.href)).searchParams.get('code')!
  const exchange = await legacy.fetch(
    new Request(`${MCP_ORIGIN}/token`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        client_id: clientId,
        redirect_uri: REDIRECT_URI,
        code_verifier: CODE_VERIFIER,
        ...(resource === undefined ? {} : { resource })
      }).toString()
    })
  )
  expect(exchange.status).toBe(200)
  const tokens = (await exchange.json()) as { access_token: string; refresh_token: string }
  return { clientId, ...tokens }
}

function refreshRequest(clientId: string, refreshToken: string): Request {
  return new Request(`${MCP_ORIGIN}/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      refresh_token: refreshToken,
      client_id: clientId
    }).toString()
  })
}

/** The current worker's token endpoint. */
function refresh(clientId: string, refreshToken: string): Promise<Response> {
  return exports.default.fetch(refreshRequest(clientId, refreshToken))
}

async function listTools(accessToken: string): Promise<{ status: number; tools?: string[] }> {
  const response = await exports.default.fetch(modernMcpRequest(accessToken, 'tools/list'))
  if (response.status !== 200) return { status: response.status }
  const body = await parseMcpResult(response)
  return { status: 200, tools: body.result?.tools?.map((tool) => tool.name) }
}

/** Cloudflare's token endpoint rotates the upstream grant; count the rotations. */
function useUpstreamRefresh(): () => string[] {
  const seen: string[] = []
  server.use(
    http.post('https://dash.cloudflare.com/oauth2/token', async ({ request }) => {
      seen.push(new URLSearchParams(await request.text()).get('refresh_token') ?? '')
      return HttpResponse.json({
        access_token: 'upstream-access-2',
        expires_in: 3600,
        refresh_token: 'upstream-refresh-2',
        scope: 'user:read account:read offline_access',
        token_type: 'bearer'
      })
    }),
    http.get('https://api.cloudflare.com/client/v4/user', () =>
      HttpResponse.json(cfSuccess({ id: 'user-1', email: 'user@example.com' }))
    ),
    http.get('https://api.cloudflare.com/client/v4/accounts', () =>
      HttpResponse.json(cfAccountsSuccess([{ id: 'acc-1', name: 'Account One' }]))
    )
  )
  return () => seen
}

afterEach(async () => {
  await clearKv(env.OAUTH_KV)
})

describe.each(LEGACY_DEPLOYMENTS)(
  'grants issued by workers-oauth-provider $version',
  ({ deploy }) => {
    it('serve MCP, refresh, and serve the refreshed token after the upgrade', async () => {
      const legacy = await issueWithLegacy(deploy(), MCP_RESOURCE)
      const upstreamRefreshes = useUpstreamRefresh()

      // The access token issued before the upgrade is accepted as it is.
      expect(await listTools(legacy.access_token)).toEqual({
        status: 200,
        tools: ['docs', 'search', 'execute', 'whoami']
      })

      // The refresh token is too, and the upstream Cloudflare grant rotates with it.
      const refreshed = await refresh(legacy.clientId, legacy.refresh_token)
      expect(refreshed.status).toBe(200)
      const tokens = (await refreshed.json()) as {
        access_token: string
        refresh_token: string
        resource: string
      }
      expect(tokens.resource).toBe(MCP_RESOURCE)
      expect(upstreamRefreshes()).toEqual(['upstream-refresh-1'])
      expect(await listTools(tokens.access_token)).toEqual({
        status: 200,
        tools: ['docs', 'search', 'execute', 'whoami']
      })

      // The grant is rewritten in the current format (with KV key metadata) and keeps its resource.
      const [grant] = (await env.OAUTH_KV.list({ prefix: 'grant:' })).keys
      expect(grant.metadata).toMatchObject({ resource: MCP_RESOURCE })
    })

    it('serve a grant issued without a resource, bound to the sole resource', async () => {
      const legacy = await issueWithLegacy(deploy(), undefined)
      useUpstreamRefresh()
      expect((await listTools(legacy.access_token)).status).toBe(200)
      const refreshed = await refresh(legacy.clientId, legacy.refresh_token)
      expect(refreshed.status).toBe(200)
      await expect(refreshed.json()).resolves.toMatchObject({ resource: MCP_RESOURCE })
    })
  }
)

describe('a grant bound to the bare origin, written before 0.10.1', () => {
  // Releases before 0.10.1 could bind a grant to the origin instead of the MCP endpoint; 0.10.x
  // never issues one. 1.x compares the resource exactly, and so, for these grants, did 0.10.2.
  it('fails to refresh with invalid_grant after the upgrade, as it already did on 0.10.2', async () => {
    const production = production0102()
    const legacy = await issueWithLegacy(production, MCP_RESOURCE)
    const [{ name: grantKey }] = (await env.OAUTH_KV.list({ prefix: 'grant:' })).keys
    const grant = (await env.OAUTH_KV.get(grantKey, 'json')) as Record<string, unknown>
    await env.OAUTH_KV.put(grantKey, JSON.stringify({ ...grant, resource: MCP_ORIGIN }))
    useUpstreamRefresh()

    const before = await production.fetch(refreshRequest(legacy.clientId, legacy.refresh_token))
    expect(before.status).toBe(400)

    const after = await refresh(legacy.clientId, legacy.refresh_token)
    expect(after.status).toBe(400)
    // invalid_grant tells conformant clients to start a new authorization.
    await expect(after.json()).resolves.toMatchObject({ error: 'invalid_grant' })
  })
})

