describe('MCP 2026-07-28 stateless handler', () => {
  it('serves server/discover without creating a protocol session', async () => {
    const response = await exports.default.fetch(modernMcpRequest(API_TOKEN, 'server/discover'))
    const body = await parseMcpResult(response)

    expect(response.status).toBe(200)
    expect(response.headers.get('content-type')).toContain('application/json')
    expect(response.headers.get('mcp-session-id')).toBeNull()
    expect(body).toMatchObject({
      result: {
        resultType: 'complete',
        supportedVersions: ['2026-07-28'],
        _meta: {
          [SERVER_INFO_META_KEY]: { name: 'cloudflare-api', version: '0.1.0' }
        }
      }
    })
    expect(body.result).not.toHaveProperty('serverInfo')
  })

  it.each([
    ['Code Mode', MCP_URL],
    ['non-Code-Mode', `${MCP_URL}?codemode=false`]
  ])('advertises no tool list change notifications in %s', async (_mode, url) => {
    const response = await exports.default.fetch(
      modernMcpRequest(API_TOKEN, 'server/discover', {}, { url })
    )
    const body = (await parseMcpResult(response)) as {
      result?: { capabilities?: { tools?: { listChanged?: boolean } } }
    }

    expect(response.status).toBe(200)
    expect(body.result?.capabilities?.tools).toBeDefined()
    expect(body.result?.capabilities?.tools?.listChanged).not.toBe(true)
  })

  it('advertises no tool list change notifications to 2025 clients', async () => {
    const response = await exports.default.fetch(
      new Request(MCP_URL, {
        method: 'POST',
        headers: {
          Host: MCP_HOST,
          Authorization: `Bearer ${API_TOKEN}`,
          'Content-Type': 'application/json',
          Accept: 'application/json, text/event-stream'
        },
        body: JSON.stringify({
          jsonrpc: '2.0',
          id: 1,
          method: 'initialize',
          params: {
            protocolVersion: '2025-06-18',
            capabilities: {},
            clientInfo: { name: 'cloudflare-mcp-tests', version: '1.0.0' }
          }
        })
      })
    )
    const body = (await parseMcpResult(response)) as {
      result?: { capabilities?: { tools?: { listChanged?: boolean } } }
    }

    expect(response.status).toBe(200)
    expect(body.result?.capabilities?.tools).toBeDefined()
    expect(body.result?.capabilities?.tools?.listChanged).not.toBe(true)
  })

  // The server declares no list-changed or subscribe capability, so the SDK honours none of
  // these and ends the stream itself (SDK 2.2+). An open stream would hang the read below.
  it.each([
    { toolsListChanged: true },
    { promptsListChanged: true },
    { resourcesListChanged: true },
    { resourceSubscriptions: ['file:///a'] },
    {}
  ])('acknowledges an empty subscription for %j and ends it gracefully', async (notifications) => {
    const response = await exports.default.fetch(
      modernMcpRequest(API_TOKEN, 'subscriptions/listen', { notifications }, { id: 7 })
    )

    expect(response.status).toBe(200)
    expect(response.headers.get('content-type')).toContain('text/event-stream')

    // The stream must end on its own; an open stream would hang this read.
    const frames = (await response.text())
      .split('\n')
      .filter((line) => line.startsWith('data:'))
      .map((line) => JSON.parse(line.slice('data:'.length).trim()))

    expect(frames).toHaveLength(2)
    expect(frames[0]).toEqual({
      jsonrpc: '2.0',
      method: 'notifications/subscriptions/acknowledged',
      params: {
        notifications: {},
        _meta: { 'io.modelcontextprotocol/subscriptionId': 7 }
      }
    })
    expect(frames[1]).toMatchObject({
      jsonrpc: '2.0',
      id: 7,
      result: {
        resultType: 'complete',
        _meta: { 'io.modelcontextprotocol/subscriptionId': 7 }
      }
    })
    expect(frames[1]).not.toHaveProperty('error')
  })

  it('serves modern tools/list with a complete result', async () => {
    const response = await exports.default.fetch(modernMcpRequest(API_TOKEN, 'tools/list'))
    const body = await parseMcpResult(response)

    expect(response.status).toBe(200)
    expect(body.result?.resultType).toBe('complete')
    expect(body.result?.tools?.map((tool) => tool.name)).toEqual([
      'docs',
      'search',
      'execute',
      'whoami'
    ])
  })

  it('serves a modern Code Mode tools/call', async () => {
    server.use(
      http.get(`${API_BASE}/accounts/${ACCOUNT_ID}/tokens/verify`, () =>
        HttpResponse.json(cfSuccess({ id: 'token-1', status: 'active' }))
      )
    )
    const code = `async () => cloudflare.request({ method: "GET", path: "/accounts/${ACCOUNT_ID}/tokens/verify" })`

    const response = await exports.default.fetch(
      modernMcpRequest(API_TOKEN, 'tools/call', {
        name: 'execute',
        arguments: { code }
      })
    )
    const body = await parseMcpResult(response)

    expect(response.status).toBe(200)
    expect(body.result?.resultType).toBe('complete')
    expect(body.result?.isError).toBeFalsy()
    expect(body.result?.content?.[0]?.text).toContain('"status": "active"')
  })

  it('serves a modern non-Code-Mode tools/call', async () => {
    server.use(
      http.get(`${API_BASE}/accounts/${ACCOUNT_ID}/workers/scripts`, () =>
        HttpResponse.json(cfSuccess([{ id: 'worker-a' }]))
      )
    )

    const response = await exports.default.fetch(
      modernMcpRequest(
        API_TOKEN,
        'tools/call',
        {
          name: 'get_accounts_workers_scripts',
          arguments: {}
        },
        { url: `${MCP_URL}?codemode=false` }
      )
    )
    const body = await parseMcpResult(response)

    expect(response.status).toBe(200)
    expect(body.result?.resultType).toBe('complete')
    expect(body.result?.isError).toBeFalsy()
    expect(body.result?.content?.[0]?.text).toContain('worker-a')
  })

  it('isolates authenticated props across concurrent requests', async () => {
    const firstAccount = '00000000000000000000000000000002'
    const secondAccount = '00000000000000000000000000000003'
    server.use(
      http.get(`${API_BASE}/user`, () => HttpResponse.json(cfError([], null))),
      http.get(`${API_BASE}/accounts`, ({ request }) => {
        const account =
          request.headers.get('Authorization') === 'Bearer token-a'
            ? { id: firstAccount, name: 'First' }
            : { id: secondAccount, name: 'Second' }
        return HttpResponse.json(cfAccountsSuccess([account]))
      }),
      http.get(`${API_BASE}/accounts/${firstAccount}/workers/scripts`, () =>
        HttpResponse.json(cfSuccess([{ id: 'first-worker' }]))
      ),
      http.get(`${API_BASE}/accounts/${secondAccount}/workers/scripts`, () =>
        HttpResponse.json(cfSuccess([{ id: 'second-worker' }]))
      )
    )
    const request = (token: string, id: number) =>
      modernMcpRequest(
        token,
        'tools/call',
        { name: 'get_accounts_workers_scripts', arguments: {} },
        { id, url: `${MCP_URL}?codemode=false` }
      )

    const [firstResponse, secondResponse] = await Promise.all([
      exports.default.fetch(request('token-a', 1)),
      exports.default.fetch(request('token-b', 2))
    ])
    const [first, second] = await Promise.all([
      parseMcpResult(firstResponse),
      parseMcpResult(secondResponse)
    ])

    expect(first.result?.content?.[0]?.text).toContain('first-worker')
    expect(first.result?.content?.[0]?.text).not.toContain('second-worker')
    expect(second.result?.content?.[0]?.text).toContain('second-worker')
    expect(second.result?.content?.[0]?.text).not.toContain('first-worker')
  })

  it('isolates concurrent factories with different requested tool surfaces', async () => {
    const [codemodeResponse, endpointResponse] = await Promise.all([
      exports.default.fetch(modernMcpRequest(API_TOKEN, 'tools/list', {}, { id: 1 })),
      exports.default.fetch(
        modernMcpRequest(
          API_TOKEN,
          'tools/list',
          {},
          {
            id: 2,
            url: `${MCP_URL}?codemode=false`
          }
        )
      )
    ])
    const [codemode, endpoints] = await Promise.all([
      parseMcpResult(codemodeResponse),
      parseMcpResult(endpointResponse)
    ])

    expect(codemodeResponse.status).toBe(200)
    expect(endpointResponse.status).toBe(200)
    expect(codemode.result?.tools?.map((tool) => tool.name)).toEqual([
      'docs',
      'search',
      'execute',
      'whoami'
    ])
    expect(endpoints.result?.tools?.map((tool) => tool.name)).toEqual([
      'docs',
      'whoami',
      'get_accounts_workers_scripts'
    ])
    expect(codemodeResponse.headers.get('mcp-session-id')).toBeNull()
    expect(endpointResponse.headers.get('mcp-session-id')).toBeNull()
  })

  it('rejects a mismatched modern method header', async () => {
    const response = await exports.default.fetch(
      modernMcpRequest(
        API_TOKEN,
        'tools/list',
        {},
        {
          headers: { 'Mcp-Method': 'tools/call' }
        }
      )
    )

    expect(response.status).toBe(400)
    expect(await response.json()).toMatchObject({
      error: { message: expect.stringContaining('Mcp-Method') },
      id: 1,
      jsonrpc: '2.0'
    })
  })

  it('uses automatic stateless 2025 compatibility from createMcpHandler', async () => {
    const response = await exports.default.fetch(mcpToolListRequest(API_TOKEN))
    const body = await parseMcpResult(response)

    expect(response.status).toBe(200)
    expect(response.headers.get('content-type')).toContain('text/event-stream')
    expect(response.headers.get('mcp-session-id')).toBeNull()
    expect(body.result?.tools?.map((tool) => tool.name)).toEqual([
      'docs',
      'search',
      'execute',
      'whoami'
    ])
  })

  it.each(['GET', 'DELETE'])('rejects session-only %s requests', async (method) => {
    const response = await exports.default.fetch(
      new Request(MCP_URL, {
        method,
        headers: {
          Host: MCP_HOST,
          Authorization: `Bearer ${API_TOKEN}`,
          Accept: 'application/json, text/event-stream'
        }
      })
    )

    expect(response.status).toBe(405)
    expect(await response.json()).toMatchObject({
      error: { code: -32000, message: 'Method not allowed.' },
      id: null,
      jsonrpc: '2.0'
    })
  })

  it('keeps session-only methods behind bearer authentication', async () => {
    const response = await exports.default.fetch(
      new Request(MCP_URL, {
        method: 'GET',
        headers: { Host: MCP_HOST, Accept: 'application/json, text/event-stream' }
      })
    )

    expect(response.status).toBe(401)
    expect(response.headers.get('www-authenticate')).toMatch(
      /^Bearer .*resource_metadata="https:\/\/mcp\.cloudflare\.com\/\.well-known\/oauth-protected-resource\/mcp"/
    )
    expect(await response.text()).toBe('')
  })
})

describe('tool result truncation', () => {
  // ~94K characters as pretty JSON, well past the ~24K-character cap.
  const ROWS = Array.from({ length: 2_000 }, (_, i) => ({ id: `worker-${i}`, i }))
  const ROWS_CODE = `async () => Array.from({ length: 2000 }, (_, i) => ({ id: "worker-" + i, i }))`

  async function callToolText(
    name: string,
    args: Record<string, unknown>,
    url = MCP_URL
  ): Promise<string> {
    const response = await exports.default.fetch(
      modernMcpRequest(API_TOKEN, 'tools/call', { name, arguments: args }, { url })
    )
    const body = await parseMcpResult(response)
    expect(body.result?.isError).toBeFalsy()
    return body.result?.content?.[0]?.text ?? ''
  }

  it('truncates an oversized result to valid JSON by default', async () => {
    const text = await callToolText('execute', { code: ROWS_CODE })
    const rows = JSON.parse(text)

    expect(text.length).toBeLessThanOrEqual(24_000)
    expect(rows.at(-1)).toMatch(/^--- TRUNCATED --- [\d,]+ more items$/)
    expect(rows.slice(0, -1)).toEqual(ROWS.slice(0, rows.length - 1))
  })

  it('truncates an oversized endpoint tool response to valid JSON', async () => {
    server.use(
      http.get(`${API_BASE}/accounts/${ACCOUNT_ID}/workers/scripts`, () =>
        HttpResponse.json(cfSuccess(ROWS))
      )
    )

    const text = await callToolText('get_accounts_workers_scripts', {}, `${MCP_URL}?codemode=false`)
    const body = JSON.parse(text)

    expect(text.length).toBeLessThanOrEqual(24_000)
    expect(body.success).toBe(true)
    expect(body.result.at(-1)).toMatch(/^--- TRUNCATED --- [\d,]+ more items$/)
  })

  it('returns the whole execute result with ?truncateToolResult=false', async () => {
    const text = await callToolText(
      'execute',
      { code: ROWS_CODE },
      `${MCP_URL}?truncateToolResult=false`
    )

    expect(JSON.parse(text)).toEqual(ROWS)
  })

  it('returns the whole search result with ?truncateToolResult=false', async () => {
    const text = await callToolText(
      'search',
      { code: ROWS_CODE },
      `${MCP_URL}?truncateToolResult=false`
    )

    expect(JSON.parse(text)).toEqual(ROWS)
  })

  it('returns the whole endpoint tool response with ?codemode=false&truncateToolResult=false', async () => {
    server.use(
      http.get(`${API_BASE}/accounts/${ACCOUNT_ID}/workers/scripts`, () =>
        HttpResponse.json(cfSuccess(ROWS))
      )
    )

    const text = await callToolText(
      'get_accounts_workers_scripts',
      {},
      `${MCP_URL}?codemode=false&truncateToolResult=false`
    )

    expect(JSON.parse(text)).toEqual(cfSuccess(ROWS))
  })

  it('keeps truncating for any value other than false', async () => {
    const text = await callToolText(
      'execute',
      { code: ROWS_CODE },
      `${MCP_URL}?truncateToolResult=0`
    )

    expect(text).toContain('--- TRUNCATED ---')
  })

  it('returns text for code that returns nothing', async () => {
    const text = await callToolText('execute', { code: 'async () => {}' })

    expect(text).toBe('undefined')
  })
})

describe('MCP deployment boundary', () => {
  it('does not treat longer path prefixes as the MCP endpoint', async () => {
    const response = await exports.default.fetch(
      modernMcpRequest(API_TOKEN, 'server/discover', {}, { url: `${MCP_URL}/other` })
    )

    expect(response.status).toBe(404)
  })

  it('allows the production Host and same-host browser Origin', async () => {
    const response = await exports.default.fetch(
      modernMcpRequest(API_TOKEN, 'server/discover', {}, { origin: `https://${MCP_HOST}` })
    )

    expect(response.status).toBe(200)
    expect(response.headers.get('access-control-allow-origin')).toBe(`https://${MCP_HOST}`)
    expect(response.headers.get('vary')).toContain('Origin')
  })

  it('rejects an unlisted browser Origin before probing the bearer token', async () => {
    let identityProbeCalls = 0
    server.use(
      http.get(`${API_BASE}/user`, () => {
        identityProbeCalls++
        return HttpResponse.json(cfSuccess(null))
      }),
      http.get(`${API_BASE}/accounts`, () => {
        identityProbeCalls++
        return HttpResponse.json(cfSuccess([]))
      })
    )

    const response = await exports.default.fetch(
      modernMcpRequest(
        API_TOKEN,
        'server/discover',
        {},
        {
          origin: 'https://attacker.example'
        }
      )
    )

    expect(response.status).toBe(403)
    expect(identityProbeCalls).toBe(0)
  })

  it('does not derive trust from an attacker-controlled matching Host and Origin', async () => {
    const response = await exports.default.fetch(
      modernMcpRequest(
        API_TOKEN,
        'server/discover',
        {},
        {
          url: 'https://attacker.example/mcp',
          host: 'attacker.example',
          origin: 'https://attacker.example'
        }
      )
    )

    expect(response.status).toBe(403)
    expect(await response.json()).toMatchObject({
      error: { message: expect.stringContaining('Invalid Host') }
    })
  })

  it('serves modern CORS preflight headers without authentication', async () => {
    const response = await exports.default.fetch(
      new Request(MCP_URL, {
        method: 'OPTIONS',
        headers: {
          Host: MCP_HOST,
          Origin: `https://${MCP_HOST}`,
          'Access-Control-Request-Method': 'POST',
          'Access-Control-Request-Headers':
            'authorization, content-type, mcp-method, mcp-name, mcp-param-account-id'
        }
      })
    )

    expect(response.status).toBe(204)
    expect(response.headers.get('access-control-allow-origin')).toBe(`https://${MCP_HOST}`)
    expect(response.headers.get('access-control-allow-headers')).toBe(
      'authorization, content-type, mcp-method, mcp-name, mcp-param-account-id'
    )
  })
})

import { env, exports } from 'cloudflare:workers'
import { Client, StreamableHTTPClientTransport } from '@modelcontextprotocol/client'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { mockIdentityProbe } from './helpers/cloudflare-api'
import { clearKv } from './helpers/kv'
import { MCP_HOST, MCP_URL, MODERN_MCP_VERSION } from './helpers/mcp'
import { clearSpec, seedSpec } from './helpers/spec'

const API_TOKEN = 'modern-client-token'
const ACCOUNT_ID = '00000000000000000000000000000001'
const SPEC_PATH = '/accounts/{account_id}/workers/scripts'

beforeEach(async () => {
  await seedSpec({
    [SPEC_PATH]: {
      get: {
        summary: 'List Workers',
        tags: ['Workers'],
        parameters: [{ name: 'account_id', in: 'path', required: true }],
        responses: {}
      }
    }
  })
  mockIdentityProbe({ accounts: [{ id: ACCOUNT_ID, name: 'Modern Client' }] })
})

afterEach(async () => {
  await clearKv(env.OAUTH_KV)
  await clearSpec()
})

describe('automatic protocol negotiation', () => {
  it('selects modern MCP, then lists and calls tools without a session', async () => {
    const requests: Array<{ method: string; rpcMethod?: string }> = []
    const workerFetch = async (input: RequestInfo | URL, init?: RequestInit) => {
      const request = new Request(input, init)
      const body =
        request.method === 'POST'
          ? ((await request.clone().json()) as { method?: string })
          : undefined
      const headers = new Headers(request.headers)
      headers.set('Host', MCP_HOST)
      headers.set('Authorization', `Bearer ${API_TOKEN}`)
      const authenticated = new Request(request, { headers })
      const response = await exports.default.fetch(authenticated)
      requests.push({ method: request.method, rpcMethod: body?.method })
      return response
    }

    const client = new Client(
      { name: 'cloudflare-mcp-modern-client-test', version: '1.0.0' },
      { versionNegotiation: { mode: 'auto' } }
    )
    const transport = new StreamableHTTPClientTransport(new URL(MCP_URL), {
      fetch: workerFetch
    })

    try {
      await client.connect(transport)

      expect(client.getProtocolEra()).toBe('modern')
      expect(client.getNegotiatedProtocolVersion()).toBe(MODERN_MCP_VERSION)
      expect(client.getServerVersion()).toEqual({ name: 'cloudflare-api', version: '0.1.0' })
      expect(client.getDiscoverResult()?.supportedVersions).toEqual([MODERN_MCP_VERSION])

      const listed = await client.listTools()
      expect(listed.tools.map((tool) => tool.name)).toEqual(['docs', 'search', 'execute', 'whoami'])

      const called = await client.callTool({
        name: 'search',
        arguments: { code: 'async () => Object.keys(spec.paths)' }
      })
      expect(called.isError).toBeFalsy()
      expect(called.content[0]).toMatchObject({ type: 'text' })
      expect(called.content[0]?.type === 'text' ? called.content[0].text : '').toContain(SPEC_PATH)

      expect(requests).toEqual([
        { method: 'POST', rpcMethod: 'server/discover' },
        { method: 'POST', rpcMethod: 'tools/list' },
        { method: 'POST', rpcMethod: 'tools/call' }
      ])
    } finally {
      await client.close()
    }
  })
})

